(()=>{
 const root=document.getElementById('reading-home'),search=document.getElementById('lesson-search');
 const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().trim();
 function sort(){const grid=root.querySelector('.grid');[...grid.querySelectorAll('article')].sort((a,b)=>normalize(a.querySelector('h3')?.textContent).localeCompare(normalize(b.querySelector('h3')?.textContent),'en',{numeric:true})).forEach(card=>grid.append(card))}
 function filter(){const part=root.querySelector('.filters button[aria-pressed=true]')?.dataset.part||'all',term=normalize(search.value);let count=0;root.querySelectorAll('.grid article').forEach(card=>{card.hidden=(part!=='all'&&card.dataset.part!==part)||!normalize(card.querySelector('h3')?.textContent||'').includes(term);if(!card.hidden)count++});document.getElementById('reading-detail').textContent=count?'':'Không tìm thấy bài phù hợp.';window.ReadingBookshelf?.refresh()}
 window.ReadingHome={filter,sort};sort();search.addEventListener('input',filter);root.querySelectorAll('.filters button').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('.filters button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter()}));filter();
 const dialog=document.getElementById('full-test-picker'),manual=document.getElementById('manual-mode'),section=document.getElementById('manual-selection'),columns=document.getElementById('manual-columns'),status=document.getElementById('selection-status'),start=document.getElementById('start-selected-test'),trigger=document.getElementById('choose-full-test');let catalog=null,selected=['','',''],loading=false;
 trigger.onclick=()=>dialog.showModal();document.getElementById('picker-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>trigger.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
 function update(){start.disabled=!selected.every(Boolean);status.textContent=selected.every(Boolean)?'Đã chọn đủ 3 passages, 40 câu. Thời gian bắt đầu khi bộ đề tải xong.':'Đã chọn '+selected.filter(Boolean).length+'/3 passages.'}
 function render(){columns.replaceChildren();[1,2,3].forEach(part=>{const col=document.createElement('div');col.className='manual-column';const heading=document.createElement('h3');heading.textContent='Passage '+part+' — '+(part===3?14:13)+' câu';const input=document.createElement('input');input.type='search';input.placeholder='Tìm tên bài…';input.setAttribute('aria-label','Tìm bài Passage '+part);const chosen=document.createElement('p');chosen.className='selected-title';chosen.textContent='Chưa chọn bài';const list=document.createElement('div');list.className='manual-list';function draw(){list.replaceChildren();const items=[...catalog].sort((a,b)=>normalize(a.title).localeCompare(normalize(b.title),'en')).filter(x=>x.part===part&&x.count===(part===3?14:13)&&normalize(x.title).includes(normalize(input.value)));items.forEach(item=>{const label=document.createElement('label');label.className='manual-choice';const radio=document.createElement('input');radio.type='radio';radio.name='manual-p'+part;radio.value=item.id;radio.checked=selected[part-1]===item.id;const text=document.createElement('span');text.textContent=item.title;const state=document.createElement('small');let done=false;try{done=FullTestCore.completed(localStorage,item.id)}catch{}state.textContent=done?'Đã làm':'Chưa làm';text.append(state);radio.onchange=()=>{selected[part-1]=item.id;chosen.textContent='Đã chọn: '+item.title;update()};label.append(radio,text);list.append(label)});if(!items.length){const empty=document.createElement('p');empty.className='manual-empty';empty.textContent='Không tìm thấy bài phù hợp.';list.append(empty)}}input.oninput=draw;col.append(heading,input,chosen,list);columns.append(col);draw()});update()}
 manual.onclick=async()=>{section.hidden=false;manual.setAttribute('aria-pressed','true');if(catalog||loading)return;loading=true;try{const r=await fetch('lesson-catalog.json',{cache:'no-cache'});if(!r.ok)throw Error();catalog=await r.json();render();columns.querySelector('input')?.focus()}catch{status.textContent='Không tải được danh sách. Bấm Tự chọn bài để thử lại.'}finally{loading=false}};
 start.onclick=()=>{try{FullTestCore.manual(catalog,selected);const params=new URLSearchParams({mode:'manual',p1:selected[0],p2:selected[1],p3:selected[2]});location.href='full-test.html?'+params.toString()}catch{status.textContent='Hãy chọn một bài hợp lệ cho mỗi Passage.'}};
})();
